CREATE TABLE IF NOT EXISTS schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE parking_locations (id bigserial PRIMARY KEY, name text NOT NULL UNIQUE, public_description text NOT NULL DEFAULT '', address text NOT NULL, timezone text NOT NULL CHECK (timezone <> ''), phone text, arrival_instructions text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE parking_zones (id bigserial PRIMARY KEY, location_id bigint NOT NULL REFERENCES parking_locations(id), name text NOT NULL, description text NOT NULL DEFAULT '', operational_notes text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, public_visible boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, UNIQUE(location_id,name));
CREATE TABLE parking_categories (id bigserial PRIMARY KEY, code text NOT NULL UNIQUE CHECK (code ~ '^[A-Z][A-Z0-9_]{1,62}$'), name text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE parking_inventory (id bigserial PRIMARY KEY, zone_id bigint NOT NULL REFERENCES parking_zones(id), category_id bigint NOT NULL REFERENCES parking_categories(id), capacity integer NOT NULL CHECK(capacity >= 0), public_description text NOT NULL DEFAULT '', restrictions text NOT NULL DEFAULT '', public_remaining_capacity boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, UNIQUE(zone_id,category_id));
CREATE TABLE parking_rate_rules (id bigserial PRIMARY KEY, location_id bigint NOT NULL REFERENCES parking_locations(id), zone_id bigint REFERENCES parking_zones(id), category_id bigint NOT NULL REFERENCES parking_categories(id), daily_rate_cents integer CHECK(daily_rate_cents >= 0), weekly_rate_cents integer CHECK(weekly_rate_cents >= 0), monthly_rate_cents integer CHECK(monthly_rate_cents >= 0), fee_cents integer NOT NULL DEFAULT 0 CHECK(fee_cents >= 0), tax_basis_points integer NOT NULL DEFAULT 0 CHECK(tax_basis_points BETWEEN 0 AND 10000), starts_at timestamptz, ends_at timestamptz, priority integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at));
CREATE TABLE parking_closures (id bigserial PRIMARY KEY, location_id bigint REFERENCES parking_locations(id), zone_id bigint REFERENCES parking_zones(id), inventory_id bigint REFERENCES parking_inventory(id), closure_type text NOT NULL CHECK(closure_type IN ('FULL_CLOSURE','CAPACITY_REDUCTION')), capacity_reduction integer NOT NULL DEFAULT 0 CHECK(capacity_reduction >= 0), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL CHECK(ends_at > starts_at), reason text NOT NULL, internal_note text NOT NULL DEFAULT '', customer_message text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, CHECK(location_id IS NOT NULL OR zone_id IS NOT NULL OR inventory_id IS NOT NULL));
CREATE TABLE parking_admin_users (id bigserial PRIMARY KEY, username text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('OWNER','STAFF')), active boolean NOT NULL DEFAULT true, failed_login_count integer NOT NULL DEFAULT 0, locked_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE parking_admin_sessions (id bigserial PRIMARY KEY, admin_user_id bigint NOT NULL REFERENCES parking_admin_users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, csrf_hash text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE parking_bookings (id bigserial PRIMARY KEY, reservation_number text NOT NULL UNIQUE, public_token text NOT NULL UNIQUE, lookup_credential_hash text NOT NULL, idempotency_hash text UNIQUE, inventory_id bigint NOT NULL REFERENCES parking_inventory(id), location_id bigint NOT NULL REFERENCES parking_locations(id), category_id bigint NOT NULL REFERENCES parking_categories(id), status text NOT NULL CHECK(status IN ('PENDING','CONFIRMED','CHECKED_IN','CHECKED_OUT','COMPLETED','CANCELLED','NO_SHOW','EXPIRED')), arrival_at timestamptz NOT NULL, departure_at timestamptz NOT NULL CHECK(departure_at > arrival_at), actual_arrival_at timestamptz, actual_departure_at timestamptz, first_name text NOT NULL, last_name text NOT NULL, mobile_phone text NOT NULL, email text NOT NULL, company_name text, tractor_unit_number text NOT NULL, license_plate text NOT NULL, license_plate_state text NOT NULL, trailer_number text, special_instructions text, assigned_zone_id bigint REFERENCES parking_zones(id), assigned_spot_label text, operational_notes text NOT NULL DEFAULT '', customer_notes text NOT NULL DEFAULT '', terms_accepted_at timestamptz NOT NULL, cancellation_terms_accepted_at timestamptz NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE parking_booking_price_snapshots (id bigserial PRIMARY KEY, booking_id bigint NOT NULL UNIQUE REFERENCES parking_bookings(id) ON DELETE RESTRICT, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE parking_booking_status_history (id bigserial PRIMARY KEY, booking_id bigint NOT NULL REFERENCES parking_bookings(id) ON DELETE RESTRICT, previous_status text, new_status text NOT NULL, actor_type text NOT NULL CHECK(actor_type IN ('CUSTOMER','ADMIN','SYSTEM')), admin_user_id bigint REFERENCES parking_admin_users(id), reason text, note text, version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE parking_booking_notes (id bigserial PRIMARY KEY, booking_id bigint NOT NULL REFERENCES parking_bookings(id) ON DELETE RESTRICT, admin_user_id bigint REFERENCES parking_admin_users(id), visibility text NOT NULL CHECK(visibility IN ('INTERNAL','CUSTOMER')), note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE parking_audit_events (id bigserial PRIMARY KEY, admin_user_id bigint REFERENCES parking_admin_users(id), action text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX bookings_availability_idx ON parking_bookings(inventory_id,arrival_at,departure_at) WHERE status IN ('PENDING','CONFIRMED','CHECKED_IN');
CREATE INDEX bookings_search_idx ON parking_bookings(reservation_number, status, arrival_at);
CREATE INDEX closures_overlap_idx ON parking_closures(starts_at,ends_at) WHERE active;
CREATE OR REPLACE FUNCTION parking_history_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'parking booking history is immutable'; END; $$;
CREATE TRIGGER parking_status_history_no_change BEFORE UPDATE OR DELETE ON parking_booking_status_history FOR EACH ROW EXECUTE FUNCTION parking_history_immutable();
CREATE TRIGGER parking_price_snapshot_no_change BEFORE UPDATE OR DELETE ON parking_booking_price_snapshots FOR EACH ROW EXECUTE FUNCTION parking_history_immutable();
